*** Begin Patch
*** Add File: /workspace/Cargo.toml
+[package]
+name = "melody_cli"
+version = "0.20.0"
+edition = "2024"
+
+[dependencies]
+clap = { version = "4.5.31", features = ["std"] }
+clap_complete = "4.5.46"
+fancy-regex = "0.14.0"
+
*** Add File: /workspace/.gitignore
+/target
+
*** Add File: /workspace/compile.sh
+#!/usr/bin/env bash
+set -euo pipefail
+
+cd "$(dirname "$0")"
+cargo build --release
+mv executable executable.original
+cp target/release/melody_cli executable
+
*** Add File: /workspace/src/main.rs
+mod melody;
+
+use std::fs;
+use std::io::{self, BufRead, IsTerminal, Read, Write};
+use std::path::Path;
+use std::process::ExitCode;
+
+use clap::builder::PossibleValue;
+use clap::{Arg, ArgAction, Command};
+use clap_complete::generate;
+use fancy_regex::Regex;
+use melody::{CompileError, Compiler, MelodyError, ParseError};
+
+const ABOUT: &str = "A CLI wrapping the Melody language compiler";
+const NO_INPUT_HELP: &str = "\
+No input file supplied and no input piped
+Try adding a path argument: 'melody ./file.mdy'
+
+A CLI wrapping the Melody language compiler
+
+Usage: melody_cli [OPTIONS] [INPUT_FILE_PATH]
+
+Arguments:
+  [INPUT_FILE_PATH]  Read from a file
+                     Use '-' and or pipe input to read from stdin
+
+Options:
+  -o, --output <OUTPUT_FILE_PATH>           Write to a file
+  -n, --no-color                            Print output with no color
+  -r, --repl                                Start the Melody REPL
+      --generate-completions <completions>  Outputs completions for the selected shell
+                                            To use, write the output to the appropriate location for your shell
+  -t, --test <test>                         Test the compiled regex against a string
+  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
+  -h, --help                                Print help
+  -V, --version                             Print version";
+
+fn build_command() -> Command {
+    Command::new("melody_cli")
+        .about(ABOUT)
+        .disable_help_subcommand(true)
+        .arg(
+            Arg::new("input_file_path")
+                .value_name("INPUT_FILE_PATH")
+                .index(1)
+                .help("Read from a file\nUse '-' and or pipe input to read from stdin")
+                .conflicts_with("generate_completions"),
+        )
+        .arg(
+            Arg::new("output")
+                .short('o')
+                .long("output")
+                .value_name("OUTPUT_FILE_PATH")
+                .help("Write to a file")
+                .conflicts_with_all(["test", "test_file", "generate_completions"]),
+        )
+        .arg(
+            Arg::new("no_color")
+                .short('n')
+                .long("no-color")
+                .action(ArgAction::SetTrue)
+                .help("Print output with no color"),
+        )
+        .arg(
+            Arg::new("repl")
+                .short('r')
+                .long("repl")
+                .action(ArgAction::SetTrue)
+                .help("Start the Melody REPL")
+                .conflicts_with_all(["test", "test_file", "generate_completions"]),
+        )
+        .arg(
+            Arg::new("generate_completions")
+                .long("generate-completions")
+                .value_name("completions")
+                .help(
+                    "Outputs completions for the selected shell\nTo use, write the output to the appropriate location for your shell",
+                )
+                .conflicts_with_all(["output", "test", "test_file", "repl", "input_file_path"]),
+        )
+        .arg(
+            Arg::new("test")
+                .short('t')
+                .long("test")
+                .value_name("test")
+                .help("Test the compiled regex against a string")
+                .conflicts_with("test_file"),
+        )
+        .arg(
+            Arg::new("test_file")
+                .short('f')
+                .long("test-file")
+                .value_name("test-file")
+                .help("Test the compiled regex against the contents of a file"),
+        )
+}
+
+fn completion_command() -> Command {
+    build_command().name("melody").bin_name("melody")
+}
+
+fn parse_args() -> Result<clap::ArgMatches, clap::Error> {
+    let bin_name = std::env::args()
+        .next()
+        .and_then(|path| {
+            Path::new(&path)
+                .file_name()
+                .map(|name| name.to_string_lossy().into_owned())
+        })
+        .unwrap_or_else(|| "executable".to_string());
+
+    build_command()
+        .bin_name(bin_name)
+        .try_get_matches_from(std::env::args_os())
+}
+
+fn main() -> ExitCode {
+    match run() {
+        Ok(code) => code,
+        Err((code, message)) => {
+            eprintln!("{message}");
+            code
+        }
+    }
+}
+
+fn run() -> Result<ExitCode, (ExitCode, String)> {
+    let matches = match parse_args() {
+        Ok(matches) => matches,
+        Err(err) => {
+            let code = match err.kind() {
+                clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion => {
+                    ExitCode::SUCCESS
+                }
+                _ => ExitCode::from(2),
+            };
+
+            let mut text = err.to_string();
+            while text.ends_with('\n') {
+                text.pop();
+            }
+
+            if matches!(err.kind(), clap::error::ErrorKind::DisplayHelp) {
+                println!("{text}");
+            } else if matches!(err.kind(), clap::error::ErrorKind::DisplayVersion) {
+                println!("{text}");
+            } else {
+                return Err((code, text));
+            }
+
+            return Ok(code);
+        }
+    };
+
+    let stdin_is_terminal = io::stdin().is_terminal();
+    let stdout_is_terminal = io::stdout().is_terminal();
+
+    if matches.get_flag("repl") {
+        if !stdin_is_terminal || !stdout_is_terminal {
+            return Err((
+                ExitCode::from(64),
+                "Error: repl argument supplied with piped input or output".to_string(),
+            ));
+        }
+
+        run_repl()?;
+        return Ok(ExitCode::SUCCESS);
+    }
+
+    if let Some(shell) = matches.get_one::<String>("generate_completions") {
+        return run_completions(shell);
+    }
+
+    let input = read_input(matches.get_one::<String>("input_file_path"), stdin_is_terminal)?;
+    let compiler = Compiler::new(&input);
+    let regex = compiler.compile().map_err(format_compile_error)?;
+
+    if let Some(test_value) = matches.get_one::<String>("test") {
+        let engine_regex = build_engine_regex(&regex)?;
+        let matched = engine_regex
+            .is_match(test_value)
+            .map_err(|err| (ExitCode::from(65), format!("Error: {err}")))?;
+        println!("'{}' {}", shorten_for_display(test_value), if matched { "matched" } else { "did not match" });
+        return Ok(ExitCode::SUCCESS);
+    }
+
+    if let Some(test_file) = matches.get_one::<String>("test_file") {
+        let test_contents = fs::read_to_string(test_file).map_err(|_| {
+            (
+                ExitCode::from(74),
+                format!("Error: unable read file at path {test_file}"),
+            )
+        })?;
+        let engine_regex = build_engine_regex(&regex)?;
+        let matched = engine_regex
+            .is_match(&test_contents)
+            .map_err(|err| (ExitCode::from(65), format!("Error: {err}")))?;
+        println!("{test_file} {}", if matched { "matched" } else { "did not match" });
+        return Ok(ExitCode::SUCCESS);
+    }
+
+    if let Some(output_path) = matches.get_one::<String>("output") {
+        fs::write(output_path, regex.as_bytes())
+            .map_err(|_| (ExitCode::from(74), format!("Error: {output_path}")))?;
+    } else {
+        println!("{regex}");
+    }
+
+    Ok(ExitCode::SUCCESS)
+}
+
+fn read_input(path: Option<&String>, stdin_is_terminal: bool) -> Result<String, (ExitCode, String)> {
+    match path {
+        Some(path) if path != "-" => fs::read_to_string(path).map_err(|_| {
+            (
+                ExitCode::from(65),
+                format!("Error: unable read file at path {path}"),
+            )
+        }),
+        Some(_) => read_stdin(),
+        None if !stdin_is_terminal => read_stdin(),
+        None => Err((ExitCode::from(66), NO_INPUT_HELP.to_string())),
+    }
+}
+
+fn read_stdin() -> Result<String, (ExitCode, String)> {
+    let mut input = String::new();
+    io::stdin()
+        .read_to_string(&mut input)
+        .map_err(|err| (ExitCode::from(74), format!("Error: {err}")))?;
+    Ok(input)
+}
+
+fn run_completions(shell: &str) -> Result<ExitCode, (ExitCode, String)> {
+    let mut cmd = completion_command();
+    let stdout = io::stdout();
+    let mut handle = stdout.lock();
+
+    match shell {
+        "bash" => generate(clap_complete::Shell::Bash, &mut cmd, "melody", &mut handle),
+        "zsh" => generate(clap_complete::Shell::Zsh, &mut cmd, "melody", &mut handle),
+        "fish" => generate(clap_complete::Shell::Fish, &mut cmd, "melody", &mut handle),
+        "elvish" => generate(clap_complete::Shell::Elvish, &mut cmd, "melody", &mut handle),
+        "powershell" => {
+            generate(clap_complete::Shell::PowerShell, &mut cmd, "melody", &mut handle)
+        }
