+fn translate_named_groups(regex: &str) -> String {
+    let mut output = String::with_capacity(regex.len());
+    let bytes = regex.as_bytes();
+    let mut idx = 0;
+    while idx < bytes.len() {
+        if idx + 2 < bytes.len() && bytes[idx] == b'(' && bytes[idx + 1] == b'?' && bytes[idx + 2] == b'<' {
+            if idx + 3 < bytes.len() && bytes[idx + 3] != b'=' && bytes[idx + 3] != b'!' {
+                output.push_str("(?P<");
