+            Ok(CompiledExpr {
+                regex,
+                quantifier_mode: QuantifierMode::AsIs,
+            })
+        }
+        Expr::Assertion(assertion) => {
+            let regex = match assertion {
+                Assertion::Ahead(items) => format!("(?={})", compile_sequence(items)?),
+                Assertion::Behind(items) => format!("(?<={})", compile_sequence(items)?),
+                Assertion::NotAhead(items) => format!("(?!{})", compile_sequence(items)?),
+                Assertion::NotBehind(items) => format!("(?<!{})", compile_sequence(items)?),
