#!/usr/bin/env python3

from __future__ import annotations

import os
import subprocess
import sys
from dataclasses import dataclass
from typing import Iterable, Iterator, List, Optional, Sequence, Tuple


ABOUT = "A CLI wrapping the Melody language compiler"
VERSION = "melody_cli 0.20.0"
HELP_TEMPLATE = """A CLI wrapping the Melody language compiler

Usage: {bin_name} [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version"""
NO_INPUT_HELP = """No input file supplied and no input piped
Try adding a path argument: 'melody ./file.mdy'

A CLI wrapping the Melody language compiler

Usage: melody_cli [OPTIONS] [INPUT_FILE_PATH]

Arguments:
  [INPUT_FILE_PATH]  Read from a file
                     Use '-' and or pipe input to read from stdin

Options:
  -o, --output <OUTPUT_FILE_PATH>           Write to a file
  -n, --no-color                            Print output with no color
  -r, --repl                                Start the Melody REPL
      --generate-completions <completions>  Outputs completions for the selected shell
                                            To use, write the output to the appropriate location for your shell
  -t, --test <test>                         Test the compiled regex against a string
  -f, --test-file <test-file>               Test the compiled regex against the contents of a file
  -h, --help                                Print help
  -V, --version                             Print version"""
REPL_BANNER = """Melody REPL v0.20.0

Commands:

- :u, :undo - undo the latest line
- :r, :redo - redo the latest undo
- :c, :clear - clear all REPL history and previous input
- :s, :source - print all previously entered lines
- :e, :exit - exit the REPL
"""


class CliExit(Exception):
    def __init__(self, code: int, message: str = "", *, stdout: bool = False) -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.stdout = stdout


class MelodyError(Exception):
    pass


class CompileError(MelodyError):
    pass


class ParseError(MelodyError):
    def __init__(self, text: str, offset: int, expected: str) -> None:
        self.text = text
        self.offset = offset
        self.expected = expected
        super().__init__(self.format())

    def format(self) -> str:
        line_number = 1
        line_start = 0
        idx = 0
        while idx < min(self.offset, len(self.text)):
            if self.text[idx] == "\n":
                line_number += 1
                line_start = idx + 1
            idx += 1

        line_end = self.text.find("\n", line_start)
        if line_end == -1:
            line_end = len(self.text)
        line_text = self.text[line_start:line_end]
        column = len(self.text[line_start:self.offset]) + 1
        pointer = " " * max(column - 1, 0)
        return (
            f"Error:  --> {line_number}:{column}\n"
            "  |\n"
            f"{line_number} | {line_text}\n"
            f"  | {pointer}^---\n"
            "  |\n"
            f"  = expected {self.expected}"
        )


@dataclass
class Literal:
    regex: str
    atom_count: int
    raw: bool = False


@dataclass
class Symbol:
    name: str


@dataclass
class NegatedSymbol:
    name: str


@dataclass
class Group:
    kind: str
    items: List["Expr"]
    name: Optional[str] = None


@dataclass
class Assertion:
    kind: str
    items: List["Expr"]


@dataclass
class Quantified:
    kind: str
    target: "Expr"
    amount: Optional[str] = None
    amount_end: Optional[str] = None


Expr = Literal | Symbol | NegatedSymbol | Group | Assertion | Quantified


@dataclass
class CompiledExpr:
    regex: str
    quantifier_mode: str


class Parser:
    def __init__(self, text: str) -> None:
        self.text = text
        self.offset = 0

    def parse(self) -> List[Expr]:
        items: List[Expr] = []
        self.skip_ws()
        while not self.eof():
            items.append(self.parse_expr(allow_quantifier=True))
            self.skip_ws()
        return items

    def parse_expr(self, *, allow_quantifier: bool) -> Expr:
        self.skip_ws()
        if self.eof():
            raise self.error("root")

        if self.consume_keyword("not"):
            self.skip_ws()
            if self.consume_keyword("ahead"):
                return Assertion("not_ahead", self.parse_block_items())
            if self.consume_keyword("behind"):
                return Assertion("not_behind", self.parse_block_items())
            if self.peek() == "<":
                symbol = self.parse_symbol_name()
                self.expect_char(";", "amount, class_content, or assertion_type")
                return NegatedSymbol(symbol)
            raise self.error("amount, class_content, or assertion_type")

        if allow_quantifier:
            quantified = self.try_parse_quantifier()
            if quantified is not None:
                return quantified

        if self.consume_keyword("match"):
            return Group("match", self.parse_block_items())
        if self.consume_keyword("either"):
            return Group("either", self.parse_block_items())
        if self.consume_keyword("capture"):
            self.skip_ws()
            name = None if self.peek() == "{" else self.parse_capture_name()
            return Group("capture", self.parse_block_items(), name)
        if self.consume_keyword("ahead"):
            return Assertion("ahead", self.parse_block_items())
        if self.consume_keyword("behind"):
            return Assertion("behind", self.parse_block_items())

        ch = self.peek()
        if ch == '"':
            literal = self.parse_literal('"')
            self.expect_char(";", "root")
            return literal
        if ch == "'":
            literal = self.parse_literal("'")
            self.expect_char(";", "root")
            return literal
        if ch == "`":
            literal = self.parse_raw()
            self.expect_char(";", "root")
            return literal
        if ch == "<":
            symbol = self.parse_symbol_name()
            self.expect_char(";", "root")
            return Symbol(symbol)
        raise self.error("root")

    def try_parse_quantifier(self) -> Optional[Quantified]:
        checkpoint = self.offset
        self.skip_ws()

        for keyword, kind in (("some", "some"), ("any", "any"), ("option", "option")):
            if self.consume_keyword(keyword):
                self.skip_ws()
                if self.consume_keyword("of"):
                    return Quantified(kind, self.parse_quantified_target())
                self.offset = checkpoint
                return None

        amount = self.try_parse_digits()
        if amount is None:
            self.offset = checkpoint
            return None

        self.skip_ws()
        if self.consume_keyword("to"):
            self.skip_ws()
            amount_end = self.try_parse_digits()
            if amount_end is None:
                raise self.error("digit")
            self.skip_ws()
            if not self.consume_keyword("of"):
                self.offset = checkpoint
                return None
            return Quantified("range", self.parse_quantified_target(), amount, amount_end)

        if self.consume_keyword("of"):
            return Quantified("exact", self.parse_quantified_target(), amount)

        self.offset = checkpoint
        return None

    def parse_quantified_target(self) -> Expr:
        self.skip_ws()
        if self.eof():
            raise self.error(
                "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
            )

        if self.consume_keyword("not"):
            self.skip_ws()
            if self.consume_keyword("ahead"):
                return Assertion("not_ahead", self.parse_block_items())
            if self.consume_keyword("behind"):
                return Assertion("not_behind", self.parse_block_items())
            if self.peek() == "<":
                symbol = self.parse_symbol_name()
                self.expect_char(
                    ";",
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )
                return NegatedSymbol(symbol)
            raise self.error("amount or assertion_type")

        if self.consume_keyword("match"):
            return Group("match", self.parse_block_items())
        if self.consume_keyword("either"):
            return Group("either", self.parse_block_items())
        if self.consume_keyword("capture"):
            self.skip_ws()
            name = None if self.peek() == "{" else self.parse_capture_name()
            return Group("capture", self.parse_block_items(), name)
        if self.consume_keyword("ahead"):
            return Assertion("ahead", self.parse_block_items())
        if self.consume_keyword("behind"):
            return Assertion("behind", self.parse_block_items())

        ch = self.peek()
        expected = (
            "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
        )
        if ch == '"':
            literal = self.parse_literal('"')
            self.expect_char(";", expected)
            return literal
        if ch == "'":
            literal = self.parse_literal("'")
            self.expect_char(";", expected)
            return literal
        if ch == "`":
            literal = self.parse_raw()
            self.expect_char(";", expected)
            return literal
        if ch == "<":
            symbol = self.parse_symbol_name()
            self.expect_char(";", expected)
            return Symbol(symbol)
        raise self.error(expected)

    def parse_block_items(self) -> List[Expr]:
        self.skip_ws()
        self.expect_char("{", "block")
        self.skip_ws()
        if self.peek() == "}":
            raise self.error(
                "literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation"
            )
        items: List[Expr] = []
        while self.peek() != "}":
            items.append(self.parse_expr(allow_quantifier=True))
            self.skip_ws()
            if self.eof():
                raise self.error("}")
        self.advance()
        return items

    def parse_capture_name(self) -> str:
        parts: List[str] = []
        while True:
            self.skip_ws()
            if self.peek() == "{":
                break
            start = self.offset
            ident = self.parse_identifier()
            if ident is None:
                raise ParseError(self.text, start, "block or identifier")
            parts.append(ident)
            self.skip_ws()
            if self.peek() == "{":
                break
        return " ".join(parts)

    def parse_literal(self, quote: str) -> Literal:
        start = self.offset
        self.advance()
        regex_parts: List[str] = []
        atom_count = 0
        while not self.eof():
            ch = self.peek()
            if ch == quote:
                self.advance()
                return Literal("".join(regex_parts), atom_count, raw=False)
            if ch == "\\":
                self.advance()
                if self.eof():
                    raise ParseError(self.text, start, "root")
                escaped = self.peek()
                if escaped == "\\":
                    regex_parts.append("\\\\")
                elif escaped == '"' and quote == '"':
                    regex_parts.append('"')
                elif escaped == "'" and quote == "'":
                    regex_parts.append("'")
                elif escaped == "n":
                    regex_parts.append("\\n")
                elif escaped == "t":
                    regex_parts.append("\\t")
                elif escaped == "r":
                    regex_parts.append("\\r")
                elif escaped == "b":
                    regex_parts.append("\\b")
                else:
                    raise ParseError(self.text, start, "root")
                atom_count += 1
                self.advance()
                continue
            regex_parts.append(escape_literal_char(ch))
            atom_count += 1
            self.advance()
        raise ParseError(self.text, start, "root")

    def parse_raw(self) -> Literal:
        start = self.offset
        self.advance()
        parts: List[str] = []
        while not self.eof():
            ch = self.peek()
            if ch == "`":
                self.advance()
                regex = "".join(parts)
                return Literal(regex, count_regex_atoms(regex), raw=True)
            if ch == "\\":
                self.advance()
                if self.eof():
                    raise ParseError(self.text, start, "root")
                escaped = self.peek()
                if escaped == "\\":
                    parts.append("\\\\")
                elif escaped == "`":
                    parts.append("`")
                else:
                    raise ParseError(self.text, start, "root")
                self.advance()
                continue
            parts.append(ch)
            self.advance()
        raise ParseError(self.text, start, "root")

    def parse_symbol_name(self) -> str:
        start = self.offset
        self.expect_char("<", "symbol_identifier")
        parts: List[str] = []
        while True:
            self.skip_ws()
            ident_start = self.offset
            ident = self.parse_identifier()
            if ident is None:
                raise ParseError(self.text, max(ident_start, start + 1), "symbol_identifier")
            parts.append(ident)
            self.skip_ws()
            if self.peek() == ">":
                self.advance()
                return " ".join(parts)

    def parse_identifier(self) -> Optional[str]:
        start = self.offset
        out: List[str] = []
        while not self.eof():
            ch = self.peek()
            if ch.isalpha() or ch == "_":
                out.append(ch)
                self.advance()
            else:
                break
        if not out:
            self.offset = start
            return None
        return "".join(out)

    def try_parse_digits(self) -> Optional[str]:
        start = self.offset
        out: List[str] = []
        while not self.eof():
            ch = self.peek()
            if ch.isdigit():
                out.append(ch)
                self.advance()
            else:
                break
        if not out:
            self.offset = start
            return None
        return "".join(out)

    def consume_keyword(self, keyword: str) -> bool:
        checkpoint = self.offset
        self.skip_ws()
        if not self.text.startswith(keyword, self.offset):
            self.offset = checkpoint
            return False
        end = self.offset + len(keyword)
        if end < len(self.text):
            next_char = self.text[end]
            if next_char.isalpha() or next_char == "_" or next_char.isdigit():
                self.offset = checkpoint
                return False
        self.offset = end
        return True

    def expect_char(self, char: str, expected: str) -> None:
        self.skip_ws()
        if self.peek() != char:
            raise self.error(expected)
        self.advance()

    def skip_ws(self) -> None:
        while not self.eof() and self.peek().isspace():
            self.advance()

    def peek(self) -> str:
        if self.eof():
            return ""
        return self.text[self.offset]

    def advance(self) -> None:
        if not self.eof():
            self.offset += 1

    def eof(self) -> bool:
        return self.offset >= len(self.text)

    def error(self, expected: str) -> ParseError:
        return ParseError(self.text, self.offset, expected)


def escape_literal_char(ch: str) -> str:
    if ch in ".+*?()[]{}^$|\\":
        return "\\" + ch
    return ch


def count_regex_atoms(pattern: str) -> int:
    if not pattern:
        return 0
    idx = 0
    atoms = 0
    while idx < len(pattern):
        ch = pattern[idx]
        if ch == "\\":
            atoms += 1
            idx += 1
            if idx < len(pattern) and pattern[idx] == "k" and idx + 1 < len(pattern) and pattern[idx + 1] == "<":
                idx += 2
                while idx < len(pattern) and pattern[idx] != ">":
                    idx += 1
            elif idx < len(pattern) and pattern[idx] == "p":
                while idx < len(pattern) and pattern[idx] != "}":
                    idx += 1
            idx += 1
            continue
        if ch == "[":
            atoms += 1
            idx += 1
            while idx < len(pattern):
                if pattern[idx] == "\\":
                    idx += 2
                    continue
                if pattern[idx] == "]":
                    idx += 1
                    break
                idx += 1
            continue
        if ch == "(":
            atoms += 1
            depth = 1
            idx += 1
            while idx < len(pattern) and depth > 0:
                if pattern[idx] == "\\":
                    idx += 2
                    continue
                if pattern[idx] == "(":
                    depth += 1
                elif pattern[idx] == ")":
                    depth -= 1
                idx += 1
            continue
        atoms += 1
        idx += 1
    return atoms


SYMBOLS = {
    "char": ".",
    "space": " ",
    "whitespace": "\\s",
    "digit": "\\d",
    "word": "\\w",
    "newline": "\\n",
    "tab": "\\t",
    "return": "\\r",
    "null": "\\0",
    "backspace": "[\\b]",
    "boundary": "\\b",
    "start": "^",
    "end": "$",
}


def compile_symbol(name: str, negated: bool) -> str:
    if name not in SYMBOLS:
        raise CompileError("usage of an unrecognized symbol")
    if name == "char":
        if negated:
            raise CompileError("negative char not allowed")
        return "."
    if name == "space":
        return "[^ ]" if negated else " "
    if name == "whitespace":
        return "\\S" if negated else "\\s"
    if name == "digit":
        return "\\D" if negated else "\\d"
    if name == "word":
        return "\\W" if negated else "\\w"
    if name == "newline":
        return "[^\\n]" if negated else "\\n"
    if name == "tab":
        return "[^\\t]" if negated else "\\t"
    if name == "return":
        return "[^\\r]" if negated else "\\r"
    if name == "null":
        return "[^\\0]" if negated else "\\0"
    if name == "backspace":
        return "[^\\b]" if negated else "[\\b]"
    if name == "boundary":
        return "\\B" if negated else "\\b"
    if name == "start":
        if negated:
            raise CompileError("negative start not allowed")
        return "^"
    if name == "end":
        if negated:
            raise CompileError("negative end not allowed")
        return "$"
    raise CompileError("usage of an unrecognized symbol")


def compile_sequence(items: Sequence[Expr]) -> str:
    return "".join(compile_expr(item).regex for item in items)


def compile_alternatives(items: Sequence[Expr]) -> str:
    return "|".join(compile_expr(item).regex for item in items)


def compile_expr(expr: Expr) -> CompiledExpr:
    if isinstance(expr, Literal):
        return CompiledExpr(expr.regex, "as_is" if expr.atom_count == 1 else "group_if_needed")
    if isinstance(expr, Symbol):
        regex = compile_symbol(expr.name, False)
        mode = "special_symbol" if expr.name in {"start", "end"} else "as_is"
        return CompiledExpr(regex, mode)
    if isinstance(expr, NegatedSymbol):
        return CompiledExpr(compile_symbol(expr.name, True), "as_is")
    if isinstance(expr, Group):
        if expr.kind == "match":
            regex = f"(?:{compile_sequence(expr.items)})"
        elif expr.kind == "either":
            regex = f"(?:{compile_alternatives(expr.items)})"
        elif expr.kind == "capture":
            inner = compile_sequence(expr.items)
            regex = f"(?<{expr.name}>{inner})" if expr.name is not None else f"({inner})"
        else:
            raise AssertionError(expr.kind)
        return CompiledExpr(regex, "as_is")
    if isinstance(expr, Assertion):
        inner = compile_sequence(expr.items)
        mapping = {
            "ahead": f"(?={inner})",
            "behind": f"(?<={inner})",
            "not_ahead": f"(?!{inner})",
            "not_behind": f"(?<!{inner})",
        }
        return CompiledExpr(mapping[expr.kind], "assertion")
    if isinstance(expr, Quantified):
        compiled = compile_expr(expr.target)
        if compiled.quantifier_mode == "assertion":
            raise CompileError("unexpected assertion in quantifier")
        if compiled.quantifier_mode == "special_symbol":
            raise CompileError("unexpected special symbol in quantifier")
        suffix = quantifier_suffix(expr)
        if compiled.quantifier_mode == "group_if_needed":
            return CompiledExpr(f"(?:{compiled.regex}){suffix}", "group_if_needed")
        return CompiledExpr(f"{compiled.regex}{suffix}", "group_if_needed")
    raise AssertionError(type(expr))


def quantifier_suffix(expr: Quantified) -> str:
    if expr.kind == "some":
        return "+"
    if expr.kind == "any":
        return "*"
    if expr.kind == "option":
        return "?"
    if expr.kind == "exact":
        assert expr.amount is not None
        return f"{{{expr.amount}}}"
    if expr.kind == "range":
        assert expr.amount is not None and expr.amount_end is not None
        try:
            if int(expr.amount) > int(expr.amount_end):
                raise CompileError("usage of an invalid quantifier range")
        except ValueError:
            pass
        return f"{{{expr.amount},{expr.amount_end}}}"
    raise AssertionError(expr.kind)


def compile_program(source: str) -> Tuple[List[Expr], str]:
    parser = Parser(source)
    expressions = parser.parse()
    regex = "".join(compile_expr(expr).regex for expr in expressions)
    return expressions, regex


def display_token(value: str) -> str:
    if len(value) > 10:
        return value[:10] + "..."
    return value


def program_has_raw(expressions: Sequence[Expr]) -> bool:
    for expr in expressions:
        if isinstance(expr, Literal) and expr.raw:
            return True
        if isinstance(expr, Group) and program_has_raw(expr.items):
            return True
        if isinstance(expr, Assertion) and program_has_raw(expr.items):
            return True
        if isinstance(expr, Quantified) and program_has_raw([expr.target]):
            return True
    return False


def iter_capture_names(regex: str) -> Iterator[str]:
    idx = 0
    while idx < len(regex) - 2:
        if regex[idx:idx + 3] == "(?<":
            next_char = regex[idx + 3] if idx + 3 < len(regex) else ""
            if next_char not in ("=", "!"):
                end = regex.find(">", idx + 3)
                if end != -1:
                    yield regex[idx + 3:end]
                    idx = end
        idx += 1


def validate_regex(regex: str) -> None:
    seen: set[str] = set()
    for name in iter_capture_names(regex):
        if " " in name:
            raise CliExit(
                65,
                f"Error: could not compile regex\nCause: invalid token at named capture group identifier\nRegex: {regex}",
            )
        if name in seen:
            raise CliExit(
                65,
                f"Error: could not compile regex\nCause: duplicate capture group name\nRegex: {regex}",
            )
        seen.add(name)


def transform_regex_for_perl(regex: str) -> str:
    out: List[str] = []
    idx = 0
    while idx < len(regex):
        if regex.startswith("\\b", idx) or regex.startswith("\\B", idx):
            atom = regex[idx:idx + 2]
            quant, width = read_quantifier(regex, idx + 2)
            if quant is not None:
                out.append(f"(?:{atom}){quant}")
                idx += 2 + width
                continue
        out.append(regex[idx])
        idx += 1
    return "".join(out)


def read_quantifier(regex: str, start: int) -> Tuple[Optional[str], int]:
    if start >= len(regex):
        return None, 0
    if regex[start] in "*+?":
        return regex[start], 1
    if regex[start] == "{":
        end = regex.find("}", start + 1)
        if end != -1:
            return regex[start:end + 1], end - start + 1
    return None, 0


def match_with_perl(regex: str, text: str) -> bool:
    perl_regex = transform_regex_for_perl(regex)
    payload = perl_regex.encode("utf-8") + b"\0" + text.encode("utf-8")
    code = (
        "use strict; use warnings; "
        "my $data = do { local $/; <STDIN> }; "
        "my ($pattern, $text) = split(/\\0/, $data, 2); "
        "my $re = eval { qr/$pattern/ }; "
        "if ($@) { chomp $@; print STDERR $@; exit 2; } "
        "exit(($text =~ /$re/) ? 0 : 1);"
    )
    completed = subprocess.run(
        ["perl", "-e", code],
        input=payload,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if completed.returncode == 0:
        return True
    if completed.returncode == 1:
        return False
    cause = completed.stderr.decode("utf-8", "replace").strip()
    raise CliExit(65, f"Error: could not compile regex\nCause: {cause}\nRegex: {regex}")


def evaluate_match(expressions: Sequence[Expr], regex: str, text: str) -> bool:
    validate_regex(regex)
    if program_has_raw(expressions):
        return match_with_perl(regex, text)
    return search_ast(expressions, text)


def search_ast(expressions: Sequence[Expr], text: str) -> bool:
    for start in range(len(text) + 1):
        if match_sequence(expressions, text, start):
            return True
    return False


def match_sequence(expressions: Sequence[Expr], text: str, start: int) -> bool:
    return any(end is not None for end in match_sequence_positions(expressions, text, start))


def match_sequence_positions(expressions: Sequence[Expr], text: str, start: int) -> Iterator[Optional[int]]:
    positions = [start]
    for expr in expressions:
        next_positions: List[int] = []
        for pos in positions:
            next_positions.extend(match_expr_positions(expr, text, pos))
        positions = dedupe_positions(next_positions)
        if not positions:
            return iter(())
    return iter(positions)


def dedupe_positions(values: Iterable[int]) -> List[int]:
    seen: set[int] = set()
    out: List[int] = []
    for value in values:
        if value not in seen:
            seen.add(value)
            out.append(value)
    return out


def match_expr_positions(expr: Expr, text: str, pos: int) -> List[int]:
    if isinstance(expr, Literal):
        if expr.raw:
            raise AssertionError("raw literals should use perl fallback")
        return match_literal(expr, text, pos)
    if isinstance(expr, Symbol):
        return match_symbol(expr.name, False, text, pos)
    if isinstance(expr, NegatedSymbol):
        return match_symbol(expr.name, True, text, pos)
    if isinstance(expr, Group):
        if expr.kind in {"match", "capture"}:
            return list(match_sequence_positions(expr.items, text, pos))
        if expr.kind == "either":
            positions: List[int] = []
            for item in expr.items:
                positions.extend(match_expr_positions(item, text, pos))
            return dedupe_positions(positions)
        raise AssertionError(expr.kind)
    if isinstance(expr, Assertion):
        return match_assertion(expr, text, pos)
    if isinstance(expr, Quantified):
        return match_quantified(expr, text, pos)
    raise AssertionError(type(expr))


def match_literal(expr: Literal, text: str, pos: int) -> List[int]:
    token_lengths = literal_token_lengths(expr.regex)
    idx = pos
    for token_length in token_lengths:
        end = idx + token_length
        if end > len(text):
            return []
        token = text[idx:end]
        if not literal_token_matches(expr.regex, idx - pos, token):
            return []
        idx = end
    return [idx]


def literal_token_lengths(regex: str) -> List[int]:
    lengths: List[int] = []
    idx = 0
    while idx < len(regex):
        if regex[idx] == "\\":
            lengths.append(1)
            idx += 2
        else:
            lengths.append(1)
            idx += 1
    return lengths


def literal_token_matches(regex: str, offset: int, token: str) -> bool:
    idx = 0
    token_index = 0
    consumed = 0
    while consumed < offset and idx < len(regex):
        if regex[idx] == "\\":
            idx += 2
        else:
            idx += 1
        consumed += 1
    if idx >= len(regex):
        return False
    if regex[idx] == "\\":
        escape = regex[idx + 1]
        if escape == "n":
            return token == "\n"
        if escape == "t":
            return token == "\t"
        if escape == "r":
            return token == "\r"
        if escape == "b":
            return token == "\b"
        if escape == "\\":
            return token == "\\"
        return token == escape
    return token == regex[idx]


def match_symbol(name: str, negated: bool, text: str, pos: int) -> List[int]:
    if name not in SYMBOLS:
        raise CompileError("usage of an unrecognized symbol")
    if name == "start":
        if negated:
            raise CompileError("negative start not allowed")
        return [pos] if pos == 0 else []
    if name == "end":
        if negated:
            raise CompileError("negative end not allowed")
        return [pos] if pos == len(text) else []
    if name == "boundary":
        matched = is_boundary(text, pos)
        return [pos] if (not matched if negated else matched) else []
    if pos >= len(text):
        return []
    ch = text[pos]
    matched = False
    if name == "char":
        if negated:
            raise CompileError("negative char not allowed")
        matched = ch not in "\n\r"
    elif name == "space":
        matched = ch == " "
    elif name == "whitespace":
        matched = ch.isspace()
    elif name == "digit":
        matched = "0" <= ch <= "9"
    elif name == "word":
        matched = ch == "_" or ch.isascii() and ch.isalnum()
    elif name == "newline":
        matched = ch == "\n"
    elif name == "tab":
        matched = ch == "\t"
    elif name == "return":
        matched = ch == "\r"
    elif name == "null":
        matched = ch == "\0"
    elif name == "backspace":
        matched = ch == "\b"
    else:
        raise AssertionError(name)
    if negated:
        matched = not matched
    return [pos + 1] if matched else []


def is_boundary(text: str, pos: int) -> bool:
    left = text[pos - 1] if pos > 0 else ""
    right = text[pos] if pos < len(text) else ""
    return is_word_char(left) != is_word_char(right)


def is_word_char(ch: str) -> bool:
    return bool(ch) and (ch == "_" or (ch.isascii() and ch.isalnum()))


def match_assertion(expr: Assertion, text: str, pos: int) -> List[int]:
    if expr.kind == "ahead":
        return [pos] if match_sequence(expr.items, text, pos) else []
    if expr.kind == "not_ahead":
        return [pos] if not match_sequence(expr.items, text, pos) else []
    if expr.kind == "behind":
        return [pos] if lookbehind_matches(expr.items, text, pos) else []
    if expr.kind == "not_behind":
        return [pos] if not lookbehind_matches(expr.items, text, pos) else []
    raise AssertionError(expr.kind)


def lookbehind_matches(items: Sequence[Expr], text: str, pos: int) -> bool:
    for start in range(pos + 1):
        if any(end == pos for end in match_sequence_positions(items, text, start)):
            return True
    return False


def match_quantified(expr: Quantified, text: str, pos: int) -> List[int]:
    if compile_expr(expr.target).quantifier_mode == "assertion":
        raise CompileError("unexpected assertion in quantifier")
    if compile_expr(expr.target).quantifier_mode == "special_symbol":
        raise CompileError("unexpected special symbol in quantifier")

    if expr.kind == "exact":
        assert expr.amount is not None
        return repeat_match(expr.target, text, pos, int(expr.amount), int(expr.amount))
    if expr.kind == "range":
        assert expr.amount is not None and expr.amount_end is not None
        start = int(expr.amount)
        end = int(expr.amount_end)
        if start > end:
            raise CompileError("usage of an invalid quantifier range")
        return repeat_match(expr.target, text, pos, start, end)
    if expr.kind == "some":
        return repeat_match(expr.target, text, pos, 1, None)
    if expr.kind == "any":
        return repeat_match(expr.target, text, pos, 0, None)
    if expr.kind == "option":
        return repeat_match(expr.target, text, pos, 0, 1)
    raise AssertionError(expr.kind)


def repeat_match(target: Expr, text: str, pos: int, minimum: int, maximum: Optional[int]) -> List[int]:
    results: List[int] = []

    def rec(current_pos: int, count: int) -> None:
        if count >= minimum:
            results.append(current_pos)
        if maximum is not None and count == maximum:
            return
        next_positions = match_expr_positions(target, text, current_pos)
        progressed = [next_pos for next_pos in next_positions if next_pos != current_pos]
        if not progressed:
            return
        for next_pos in progressed:
            rec(next_pos, count + 1)

    rec(pos, 0)
    return dedupe_positions(results)


@dataclass
class ParsedArgs:
    input_file_path: Optional[str] = None
    output: Optional[str] = None
    no_color: bool = False
    repl: bool = False
    generate_completions: Optional[str] = None
    test: Optional[str] = None
    test_file: Optional[str] = None
    help: bool = False
    version: bool = False


def option_label(name: str) -> str:
    return {
        "input_file_path": "[INPUT_FILE_PATH]",
        "output": "--output <OUTPUT_FILE_PATH>",
        "repl": "--repl",
        "generate_completions": "--generate-completions <completions>",
        "test": "--test <test>",
        "test_file": "--test-file <test-file>",
    }[name]


def usage_for(name: str, bin_name: str) -> str:
    return {
        "input_file_path": f"Usage: {bin_name} <INPUT_FILE_PATH>",
        "output": f"Usage: {bin_name} --output <OUTPUT_FILE_PATH> <INPUT_FILE_PATH>",
        "repl": f"Usage: {bin_name} --repl [INPUT_FILE_PATH]",
        "generate_completions": f"Usage: {bin_name} --generate-completions <completions> [INPUT_FILE_PATH]",
        "test": f"Usage: {bin_name} --test <test> [INPUT_FILE_PATH]",
        "test_file": f"Usage: {bin_name} --test-file <test-file> [INPUT_FILE_PATH]",
    }[name]


def parse_args(argv: Sequence[str], bin_name: str) -> ParsedArgs:
    parsed = ParsedArgs()
    seen: List[str] = []
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg == "--help" or arg == "-h":
            parsed.help = True
            return parsed
        if arg == "--version" or arg == "-V":
            parsed.version = True
            return parsed
        if arg in ("-o", "--output", "-t", "--test", "-f", "--test-file", "--generate-completions"):
            if index + 1 >= len(argv):
                raise CliExit(
                    2,
                    missing_value_message(arg, bin_name),
                )
            value = argv[index + 1]
            canonical = {
                "-o": "output",
                "--output": "output",
                "-t": "test",
                "--test": "test",
                "-f": "test_file",
                "--test-file": "test_file",
                "--generate-completions": "generate_completions",
            }[arg]
            if canonical == "output":
                conflict = first_conflict(seen, ("test", "test_file", "generate_completions"))
                if conflict is not None:
                    raise conflict_message(conflict, canonical, bin_name)
                parsed.output = value
            elif canonical == "test":
                conflict = first_conflict(seen, ("test_file", "repl", "output", "generate_completions"))
                if conflict is not None:
                    raise conflict_message(conflict, canonical, bin_name)
                parsed.test = value
            elif canonical == "test_file":
                conflict = first_conflict(seen, ("test", "repl", "output", "generate_completions"))
                if conflict is not None:
                    raise conflict_message(conflict, canonical, bin_name)
                parsed.test_file = value
            elif canonical == "generate_completions":
                conflict = first_conflict(seen, ("output", "test", "test_file", "repl"))
                if conflict is not None:
                    raise conflict_message(conflict, canonical, bin_name)
                if parsed.input_file_path is not None:
                    raise CliExit(
                        2,
                        f"error: the argument '[INPUT_FILE_PATH]' cannot be used with '--generate-completions <completions>'\n\n{usage_for('input_file_path', bin_name)}\n\nFor more information, try '--help'.",
                    )
                parsed.generate_completions = value
            seen.append(canonical)
            index += 2
            continue
        if arg == "-n" or arg == "--no-color":
            parsed.no_color = True
            seen.append("no_color")
            index += 1
            continue
        if arg == "-r" or arg == "--repl":
            conflict = first_conflict(seen, ("test", "test_file", "generate_completions"))
            if conflict is not None:
                raise conflict_message(conflict, "repl", bin_name)
            parsed.repl = True
            seen.append("repl")
            index += 1
            continue
        if arg.startswith("--"):
            raise CliExit(
                2,
                f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {bin_name} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
            )
        if arg.startswith("-") and arg != "-":
            raise CliExit(
                2,
                f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {bin_name} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
            )
        if parsed.generate_completions is not None:
            raise CliExit(
                2,
                f"error: the argument '[INPUT_FILE_PATH]' cannot be used with '--generate-completions <completions>'\n\n{usage_for('input_file_path', bin_name)}\n\nFor more information, try '--help'.",
            )
        if parsed.input_file_path is None:
            parsed.input_file_path = arg
            seen.append("input_file_path")
            index += 1
            continue
        raise CliExit(
            2,
            f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {bin_name} [OPTIONS] [INPUT_FILE_PATH]\n\nFor more information, try '--help'.",
        )
    return parsed


def first_conflict(seen: Sequence[str], candidates: Sequence[str]) -> Optional[str]:
    for name in seen:
        if name in candidates:
            return name
    return None


def conflict_message(existing: str, new: str, bin_name: str) -> CliExit:
    return CliExit(
        2,
        f"error: the argument '{option_label(existing)}' cannot be used with '{option_label(new)}'\n\n{usage_for(existing, bin_name)}\n\nFor more information, try '--help'.",
    )


def missing_value_message(arg: str, bin_name: str) -> str:
    long_form = {
        "-o": "--output <OUTPUT_FILE_PATH>",
        "--output": "--output <OUTPUT_FILE_PATH>",
        "-t": "--test <test>",
        "--test": "--test <test>",
        "-f": "--test-file <test-file>",
        "--test-file": "--test-file <test-file>",
        "--generate-completions": "--generate-completions <completions>",
    }[arg]
    return f"error: a value is required for '{long_form}' but none was supplied\n\nFor more information, try '--help'."


def read_input(path: Optional[str], stdin_is_tty: bool) -> str:
    if path and path != "-":
        try:
            with open(path, "r", encoding="utf-8") as handle:
                return handle.read()
        except OSError:
            raise CliExit(65, f"Error: unable read file at path {path}")
    if path == "-" or not stdin_is_tty:
        return sys.stdin.read()
    raise CliExit(66, NO_INPUT_HELP)


def write_output(path: str, regex: str) -> None:
    try:
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(regex)
    except OSError:
        raise CliExit(74, f"Error: {path}")


def load_completion(shell: str) -> str:
    base_dir = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(base_dir, "data", "completions", shell)
    with open(path, "r", encoding="utf-8") as handle:
        return handle.read()


def run_repl() -> None:
    sys.stdout.write(REPL_BANNER + "\n")
    sys.stdout.flush()
    lines: List[str] = []
    redo_stack: List[str] = []
    while True:
        sys.stdout.write("~ ")
        sys.stdout.flush()
        line = sys.stdin.readline()
        if line == "":
            return
        line = line.rstrip("\r\n")
        if line == "":
            sys.stdout.write("\n")
            continue
        if line in (":u", ":undo"):
            if lines:
                redo_stack.append(lines.pop())
                sys.stdout.write("undo\n\n")
            else:
                sys.stdout.write("nothing to undo\n\n")
            continue
        if line in (":r", ":redo"):
            if redo_stack:
                lines.append(redo_stack.pop())
                sys.stdout.write("redo\n")
                try:
                    _, regex = compile_program("\n".join(lines))
                    sys.stdout.write(regex + "\n\n")
                except MelodyError as err:
                    sys.stdout.write(format_melody_error(err) + "\n\n")
            else:
                sys.stdout.write("nothing to redo\n\n")
            continue
        if line in (":c", ":clear"):
            lines.clear()
            redo_stack.clear()
            sys.stdout.write("clear\n\n")
            continue
        if line in (":s", ":source"):
            if not lines:
                sys.stdout.write("no lines to print\n\n")
            else:
                sys.stdout.write("source\n")
                for idx, source_line in enumerate(lines, start=1):
                    sys.stdout.write(f"{idx} {source_line}\n")
                sys.stdout.write("\n")
            continue
        if line in (":e", ":exit"):
            sys.stdout.write("exit\n")
            return
        if line.startswith(":"):
            sys.stdout.write(f'Error: unrecognized command "{line}"\n\n')
            continue

        next_source = "\n".join(lines + [line])
        try:
            _, regex = compile_program(next_source)
        except MelodyError as err:
            sys.stdout.write(format_melody_error(err) + "\n\n")
            continue
        lines.append(line)
        redo_stack.clear()
        sys.stdout.write(regex + "\n\n")


def format_melody_error(err: MelodyError) -> str:
    if isinstance(err, ParseError):
        return err.format()
    return f"Error: {err}"


def main(argv: Sequence[str]) -> int:
    bin_name = os.path.basename(argv[0]) or "executable"
    try:
        parsed = parse_args(argv[1:], bin_name)
        if parsed.help:
            sys.stdout.write(HELP_TEMPLATE.format(bin_name=bin_name) + "\n")
            return 0
        if parsed.version:
            sys.stdout.write(VERSION + "\n")
            return 0

        stdin_is_tty = os.isatty(sys.stdin.fileno())
        stdout_is_tty = os.isatty(sys.stdout.fileno())

        if parsed.repl:
            if not stdin_is_tty or not stdout_is_tty:
                raise CliExit(64, "Error: repl argument supplied with piped input or output")
            run_repl()
            return 0

        if parsed.generate_completions is not None:
            shell = parsed.generate_completions
            if shell not in {"bash", "zsh", "fish", "elvish", "powershell"}:
                raise CliExit(
                    0,
                    f"Unknown or unsupported shell: '{shell}'\nTry one of: 'bash', 'zsh', 'fish', 'elvish', 'powershell'",
                )
            sys.stdout.write(load_completion(shell))
            return 0

        source = read_input(parsed.input_file_path, stdin_is_tty)
        expressions, regex = compile_program(source)

        if parsed.test is not None:
            matched = evaluate_match(expressions, regex, parsed.test)
            sys.stdout.write(
                f"'{display_token(parsed.test)}' {'matched' if matched else 'did not match'}\n"
            )
            return 0

        if parsed.test_file is not None:
            try:
                with open(parsed.test_file, "r", encoding="utf-8") as handle:
                    test_text = handle.read()
            except OSError:
                raise CliExit(74, f"Error: unable read file at path {parsed.test_file}")
            matched = evaluate_match(expressions, regex, test_text)
            sys.stdout.write(f"{parsed.test_file} {'matched' if matched else 'did not match'}\n")
            return 0

        if parsed.output is not None:
            write_output(parsed.output, regex)
        else:
            sys.stdout.write(regex + "\n")
        return 0
    except CliExit as err:
        if err.message:
            stream = sys.stdout if err.stdout else sys.stderr
            stream.write(err.message + "\n")
        return err.code
    except MelodyError as err:
        sys.stderr.write(format_melody_error(err) + "\n")
        return 65


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

