use std::fmt;

#[derive(Debug)]
pub enum MelodyError {
    Parse(ParseError),
    Compile(CompileError),
}

#[derive(Debug)]
pub struct ParseError {
    input: String,
    offset: usize,
    expected: &'static str,
}

impl ParseError {
    fn new(input: &str, offset: usize, expected: &'static str) -> Self {
        Self {
            input: input.to_string(),
            offset,
            expected,
        }
    }

    pub fn format(&self) -> String {
        let (line_number, line_start) = line_number_and_start(&self.input, self.offset);
        let line_end = self.input[line_start..]
            .find('\n')
            .map(|idx| line_start + idx)
            .unwrap_or(self.input.len());
        let line_text = &self.input[line_start..line_end];
        let column = self
            .input
            .get(line_start..self.offset)
            .map(|slice| slice.chars().count() + 1)
            .unwrap_or(1);
        let pointer = " ".repeat(column.saturating_sub(1));

        format!(
            "Error:  --> {line_number}:{column}\n  |\n{line_number} | {line_text}\n  | {pointer}^---\n  |\n  = expected {}",
            self.expected
        )
    }
}

fn line_number_and_start(input: &str, offset: usize) -> (usize, usize) {
    let mut line_number = 1;
    let mut line_start = 0;
    for (idx, ch) in input.char_indices() {
        if idx >= offset {
            break;
        }
        if ch == '\n' {
            line_number += 1;
            line_start = idx + ch.len_utf8();
        }
    }
    (line_number, line_start)
}

#[derive(Debug, Clone)]
pub struct CompileError(pub String);

impl fmt::Display for CompileError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

#[derive(Debug, Clone)]
enum Expr {
    Literal(CompiledAtom),
    Symbol(Symbol),
    NegatedSymbol(Symbol),
    Group(Group),
    Assertion(Assertion),
    Quantified {
        quantifier: Quantifier,
        target: Box<Expr>,
    },
}

#[derive(Debug, Clone)]
struct CompiledAtom {
    regex: String,
    atom_count: usize,
}

#[derive(Debug, Clone)]
enum Group {
    Match(Vec<Expr>),
    Either(Vec<Expr>),
    Capture {
        name: Option<String>,
        items: Vec<Expr>,
    },
}

#[derive(Debug, Clone)]
enum Assertion {
    Ahead(Vec<Expr>),
    Behind(Vec<Expr>),
    NotAhead(Vec<Expr>),
    NotBehind(Vec<Expr>),
}

#[derive(Debug, Clone, Copy)]
enum Quantifier {
    Exact,
    Range,
    Some,
    Any,
    Option,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Symbol {
    Char,
    Space,
    Whitespace,
    Digit,
    Word,
    Newline,
    Tab,
    Return,
    Null,
    Backspace,
    Boundary,
    Start,
    End,
    Unknown(String),
}

pub struct Compiler<'a> {
    parser: Parser<'a>,
}

impl<'a> Compiler<'a> {
    pub fn new(input: &'a str) -> Self {
        Self {
            parser: Parser::new(input),
        }
    }

    pub fn compile(mut self) -> Result<String, MelodyError> {
        let expressions = self.parser.parse_root().map_err(MelodyError::Parse)?;
        let mut out = String::new();
        for expr in &expressions {
            out.push_str(&compile_expr(expr).map_err(MelodyError::Compile)?.regex);
        }
        Ok(out)
    }
}

#[derive(Debug, Clone)]
struct CompiledExpr {
    regex: String,
    quantifier_mode: QuantifierMode,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum QuantifierMode {
    AsIs,
    GroupIfNeeded,
    Assertion,
    SpecialSymbol,
}

fn compile_expr(expr: &Expr) -> Result<CompiledExpr, CompileError> {
    match expr {
        Expr::Literal(atom) => Ok(CompiledExpr {
            regex: atom.regex.clone(),
            quantifier_mode: if atom.atom_count == 1 {
                QuantifierMode::AsIs
            } else {
                QuantifierMode::GroupIfNeeded
            },
        }),
        Expr::Symbol(symbol) => {
            let regex = compile_symbol(symbol, false)?;
            let quantifier_mode = if matches!(symbol, Symbol::Start | Symbol::End) {
                QuantifierMode::SpecialSymbol
            } else {
                QuantifierMode::AsIs
            };
            Ok(CompiledExpr {
                regex,
                quantifier_mode,
            })
        }
        Expr::NegatedSymbol(symbol) => Ok(CompiledExpr {
            regex: compile_symbol(symbol, true)?,
            quantifier_mode: QuantifierMode::AsIs,
        }),
        Expr::Group(group) => {
            let regex = match group {
                Group::Match(items) => format!("(?:{})", compile_sequence(items)?),
                Group::Either(items) => format!("(?:{})", compile_alternatives(items)?),
                Group::Capture { name, items } => match name {
                    Some(name) => format!("(?<{name}>{})", compile_sequence(items)?),
                    None => format!("({})", compile_sequence(items)?),
                },
            };
            Ok(CompiledExpr {
                regex,
                quantifier_mode: QuantifierMode::AsIs,
            })
        }
        Expr::Assertion(assertion) => {
            let regex = match assertion {
                Assertion::Ahead(items) => format!("(?={})", compile_sequence(items)?),
                Assertion::Behind(items) => format!("(?<={})", compile_sequence(items)?),
                Assertion::NotAhead(items) => format!("(?!{})", compile_sequence(items)?),
                Assertion::NotBehind(items) => format!("(?<!{})", compile_sequence(items)?),
            };
            Ok(CompiledExpr {
                regex,
                quantifier_mode: QuantifierMode::Assertion,
            })
        }
        Expr::Quantified { quantifier, target } => {
            let compiled = compile_expr(target)?;
            if compiled.quantifier_mode == QuantifierMode::Assertion {
                return Err(CompileError("unexpected assertion in quantifier".to_string()));
            }
            if compiled.quantifier_mode == QuantifierMode::SpecialSymbol {
                return Err(CompileError("unexpected special symbol in quantifier".to_string()));
            }

            let suffix = quantifier.suffix(target)?;
            let regex = if compiled.quantifier_mode == QuantifierMode::GroupIfNeeded {
                format!("(?:{}){suffix}", compiled.regex)
            } else {
                format!("{}{suffix}", compiled.regex)
            };

            Ok(CompiledExpr {
                regex,
                quantifier_mode: QuantifierMode::GroupIfNeeded,
            })
        }
    }
}

fn compile_sequence(items: &[Expr]) -> Result<String, CompileError> {
    let mut out = String::new();
    for item in items {
        out.push_str(&compile_expr(item)?.regex);
    }
    Ok(out)
}

fn compile_alternatives(items: &[Expr]) -> Result<String, CompileError> {
    let mut pieces = Vec::new();
    for item in items {
        pieces.push(compile_expr(item)?.regex);
    }
    Ok(pieces.join("|"))
}

impl Quantifier {
    fn suffix(&self, target: &Expr) -> Result<String, CompileError> {
        match self {
            Quantifier::Exact => {
                let amount = exact_amount(target).expect("exact amount quantifier");
                Ok(format!("{{{amount}}}"))
            }
            Quantifier::Range => {
                let (start, end) = range_amount(target).expect("range amount quantifier");
                if start.parse::<u64>().ok().zip(end.parse::<u64>().ok()).is_some_and(|(s, e)| s > e) {
                    return Err(CompileError("usage of an invalid quantifier range".to_string()));
                }
                Ok(format!("{{{start},{end}}}"))
            }
            Quantifier::Some => Ok("+".to_string()),
            Quantifier::Any => Ok("*".to_string()),
            Quantifier::Option => Ok("?".to_string()),
        }
    }
}

fn exact_amount(target: &Expr) -> Option<String> {
    if let Expr::Quantified {
        quantifier: Quantifier::Exact,
        target,
    } = target
    {
        if let Expr::Literal(atom) = target.as_ref() {
            return Some(atom.regex.clone());
        }
    }
    None
}

fn range_amount(_target: &Expr) -> Option<(String, String)> {
    None
}

fn compile_symbol(symbol: &Symbol, negated: bool) -> Result<String, CompileError> {
    match (symbol, negated) {
        (Symbol::Char, false) => Ok(".".to_string()),
        (Symbol::Char, true) => Err(CompileError("negative char not allowed".to_string())),
        (Symbol::Space, false) => Ok(" ".to_string()),
        (Symbol::Space, true) => Ok("[^ ]".to_string()),
        (Symbol::Whitespace, false) => Ok("\\s".to_string()),
        (Symbol::Whitespace, true) => Ok("\\S".to_string()),
        (Symbol::Digit, false) => Ok("\\d".to_string()),
        (Symbol::Digit, true) => Ok("\\D".to_string()),
        (Symbol::Word, false) => Ok("\\w".to_string()),
        (Symbol::Word, true) => Ok("\\W".to_string()),
        (Symbol::Newline, false) => Ok("\\n".to_string()),
        (Symbol::Newline, true) => Ok("[^\\n]".to_string()),
        (Symbol::Tab, false) => Ok("\\t".to_string()),
        (Symbol::Tab, true) => Ok("[^\\t]".to_string()),
        (Symbol::Return, false) => Ok("\\r".to_string()),
        (Symbol::Return, true) => Ok("[^\\r]".to_string()),
        (Symbol::Null, false) => Ok("\\0".to_string()),
        (Symbol::Null, true) => Ok("[^\\0]".to_string()),
        (Symbol::Backspace, false) => Ok("[\\b]".to_string()),
        (Symbol::Backspace, true) => Ok("[^\\b]".to_string()),
        (Symbol::Boundary, false) => Ok("\\b".to_string()),
        (Symbol::Boundary, true) => Ok("\\B".to_string()),
        (Symbol::Start, false) => Ok("^".to_string()),
        (Symbol::Start, true) => Err(CompileError("negative start not allowed".to_string())),
        (Symbol::End, false) => Ok("$".to_string()),
        (Symbol::End, true) => Err(CompileError("negative end not allowed".to_string())),
        (Symbol::Unknown(_), _) => Err(CompileError("usage of an unrecognized symbol".to_string())),
    }
}

struct Parser<'a> {
    input: &'a str,
    offset: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, offset: 0 }
    }

    fn parse_root(&mut self) -> Result<Vec<Expr>, ParseError> {
        let mut expressions = Vec::new();
        self.skip_ws();
        while !self.is_eof() {
            expressions.push(self.parse_expr(true)?);
            self.skip_ws();
        }
        Ok(expressions)
    }

    fn parse_expr(&mut self, allow_quantifier: bool) -> Result<Expr, ParseError> {
        self.skip_ws();
        if self.is_eof() {
            return Err(self.error_here("root"));
        }

        if self.consume_keyword("not") {
            self.skip_ws();
            if self.consume_keyword("ahead") {
                return Ok(Expr::Assertion(Assertion::NotAhead(self.parse_block_items()?)));
            }
            if self.consume_keyword("behind") {
                return Ok(Expr::Assertion(Assertion::NotBehind(self.parse_block_items()?)));
            }
            if self.peek_char() == Some('<') {
                let symbol = self.parse_symbol()?;
                self.expect_char(';', "amount, class_content, or assertion_type")?;
                return Ok(Expr::NegatedSymbol(symbol));
            }
            return Err(self.error_here("amount, class_content, or assertion_type"));
        }

        if allow_quantifier {
            if let Some(expr) = self.try_parse_quantifier()? {
                return Ok(expr);
            }
        }

        if self.consume_keyword("match") {
            return Ok(Expr::Group(Group::Match(self.parse_block_items()?)));
        }
        if self.consume_keyword("either") {
            return Ok(Expr::Group(Group::Either(self.parse_block_items()?)));
        }
        if self.consume_keyword("capture") {
            self.skip_ws();
            let name = if self.peek_char() == Some('{') {
                None
            } else {
                Some(self.parse_capture_name()?)
            };
            return Ok(Expr::Group(Group::Capture {
                name,
                items: self.parse_block_items()?,
            }));
        }
        if self.consume_keyword("ahead") {
            return Ok(Expr::Assertion(Assertion::Ahead(self.parse_block_items()?)));
        }
        if self.consume_keyword("behind") {
            return Ok(Expr::Assertion(Assertion::Behind(self.parse_block_items()?)));
        }

        match self.peek_char() {
            Some('"') => {
                let atom = self.parse_literal('"')?;
                self.expect_char(';', "root")?;
                Ok(Expr::Literal(atom))
            }
            Some('\'') => {
                let atom = self.parse_literal('\'')?;
                self.expect_char(';', "root")?;
                Ok(Expr::Literal(atom))
            }
            Some('`') => {
                let atom = self.parse_raw()?;
                self.expect_char(';', "root")?;
                Ok(Expr::Literal(atom))
            }
            Some('<') => {
                let symbol = self.parse_symbol()?;
                self.expect_char(';', "root")?;
                Ok(Expr::Symbol(symbol))
            }
            _ => Err(self.error_here("root")),
        }
    }

    fn try_parse_quantifier(&mut self) -> Result<Option<Expr>, ParseError> {
        let checkpoint = self.offset;
        self.skip_ws();

        if self.consume_keyword("some") {
            self.skip_ws();
            if self.consume_keyword("of") {
                let target = self.parse_quantified_target()?;
                return Ok(Some(Expr::Quantified {
                    quantifier: Quantifier::Some,
                    target: Box::new(target),
                }));
            }
            self.offset = checkpoint;
            return Ok(None);
        }

        if self.consume_keyword("any") {
            self.skip_ws();
            if self.consume_keyword("of") {
                let target = self.parse_quantified_target()?;
                return Ok(Some(Expr::Quantified {
                    quantifier: Quantifier::Any,
                    target: Box::new(target),
                }));
            }
            self.offset = checkpoint;
            return Ok(None);
        }

        if self.consume_keyword("option") {
            self.skip_ws();
            if self.consume_keyword("of") {
                let target = self.parse_quantified_target()?;
                return Ok(Some(Expr::Quantified {
                    quantifier: Quantifier::Option,
                    target: Box::new(target),
                }));
            }
            self.offset = checkpoint;
            return Ok(None);
        }

        if let Some(first_amount) = self.try_parse_digits() {
            self.skip_ws();
            if self.consume_keyword("to") {
                self.skip_ws();
                let second_amount = self
                    .try_parse_digits()
                    .ok_or_else(|| self.error_here("digit"))?;
                self.skip_ws();
                if !self.consume_keyword("of") {
                    self.offset = checkpoint;
                    return Ok(None);
                }
                let target = self.parse_quantified_target()?;
                let range_literal = Expr::Literal(CompiledAtom {
                    regex: format!("{first_amount},{second_amount}"),
                    atom_count: 1,
                });
                return Ok(Some(Expr::Quantified {
                    quantifier: Quantifier::Range,
                    target: Box::new(range_literal),
                }));
            }

            if self.consume_keyword("of") {
                let target = self.parse_quantified_target()?;
                let exact_literal = Expr::Literal(CompiledAtom {
                    regex: first_amount,
                    atom_count: 1,
                });
                return Ok(Some(Expr::Quantified {
                    quantifier: Quantifier::Exact,
                    target: Box::new(exact_literal),
                }));
            }

            self.offset = checkpoint;
        }

        Ok(None)
    }

    fn parse_quantified_target(&mut self) -> Result<Expr, ParseError> {
        self.skip_ws();
        if self.is_eof() {
            return Err(self.error_here(
                "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
            ));
        }

        if self.consume_keyword("not") {
            self.skip_ws();
            if self.consume_keyword("ahead") {
                return Ok(Expr::Assertion(Assertion::NotAhead(self.parse_block_items()?)));
            }
            if self.consume_keyword("behind") {
                return Ok(Expr::Assertion(Assertion::NotBehind(self.parse_block_items()?)));
            }
            if self.peek_char() == Some('<') {
                let symbol = self.parse_symbol()?;
                self.expect_char(
                    ';',
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )?;
                return Ok(Expr::NegatedSymbol(symbol));
            }
            return Err(self.error_here("amount or assertion_type"));
        }

        if self.consume_keyword("match") {
            return Ok(Expr::Group(Group::Match(self.parse_block_items()?)));
        }
        if self.consume_keyword("either") {
            return Ok(Expr::Group(Group::Either(self.parse_block_items()?)));
        }
        if self.consume_keyword("capture") {
            self.skip_ws();
            let name = if self.peek_char() == Some('{') {
                None
            } else {
                Some(self.parse_capture_name()?)
            };
            return Ok(Expr::Group(Group::Capture {
                name,
                items: self.parse_block_items()?,
            }));
        }
        if self.consume_keyword("ahead") {
            return Ok(Expr::Assertion(Assertion::Ahead(self.parse_block_items()?)));
        }
        if self.consume_keyword("behind") {
            return Ok(Expr::Assertion(Assertion::Behind(self.parse_block_items()?)));
        }

        match self.peek_char() {
            Some('"') => {
                let atom = self.parse_literal('"')?;
                self.expect_char(
                    ';',
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )?;
                Ok(Expr::Literal(atom))
            }
            Some('\'') => {
                let atom = self.parse_literal('\'')?;
                self.expect_char(
                    ';',
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )?;
                Ok(Expr::Literal(atom))
            }
            Some('`') => {
                let atom = self.parse_raw()?;
                self.expect_char(
                    ';',
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )?;
                Ok(Expr::Literal(atom))
            }
            Some('<') => {
                let symbol = self.parse_symbol()?;
                self.expect_char(
                    ';',
                    "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
                )?;
                Ok(Expr::Symbol(symbol))
            }
            _ => Err(self.error_here(
                "literal, raw, not, range, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
            )),
        }
    }

    fn parse_block_items(&mut self) -> Result<Vec<Expr>, ParseError> {
        self.skip_ws();
        self.expect_char('{', "block")?;
        self.skip_ws();
        if self.peek_char() == Some('}') {
            return Err(self.error_here(
                "literal, raw, not, range, quantifier_quantity, group_declaration, assertion_declaration, variable_declaration, or variable_invocation",
            ));
        }
        let mut items = Vec::new();
        while self.peek_char() != Some('}') {
            items.push(self.parse_expr(true)?);
            self.skip_ws();
            if self.is_eof() {
                return Err(self.error_here("}"));
            }
        }
        self.advance_char();
        Ok(items)
    }

    fn parse_capture_name(&mut self) -> Result<String, ParseError> {
        let mut parts = Vec::new();
        loop {
            self.skip_ws();
            if self.peek_char() == Some('{') {
                break;
            }
            let start = self.offset;
            let ident = self
                .parse_identifier()
                .ok_or_else(|| ParseError::new(self.input, start, "block or identifier"))?;
            parts.push(ident);
            self.skip_ws();
            if self.peek_char() == Some('{') {
                break;
            }
        }
        Ok(parts.join(" "))
    }

    fn parse_literal(&mut self, quote: char) -> Result<CompiledAtom, ParseError> {
        let start = self.offset;
        self.advance_char();
        let mut regex = String::new();
        let mut atom_count = 0;
        while let Some(ch) = self.peek_char() {
            if ch == quote {
                self.advance_char();
                return Ok(CompiledAtom { regex, atom_count });
            }
            if ch == '\\' {
                self.advance_char();
                let escaped = self.peek_char().ok_or_else(|| ParseError::new(self.input, start, "root"))?;
                match escaped {
                    '\\' => {
                        regex.push_str("\\\\");
                        atom_count += 1;
                        self.advance_char();
                    }
                    '"' if quote == '"' => {
                        regex.push('"');
                        atom_count += 1;
                        self.advance_char();
                    }
                    '\'' if quote == '\'' => {
                        regex.push('\'');
                        atom_count += 1;
                        self.advance_char();
                    }
                    'n' => {
                        regex.push_str("\\n");
                        atom_count += 1;
                        self.advance_char();
                    }
                    't' => {
                        regex.push_str("\\t");
                        atom_count += 1;
                        self.advance_char();
                    }
                    'r' => {
                        regex.push_str("\\r");
                        atom_count += 1;
                        self.advance_char();
                    }
                    'b' => {
                        regex.push_str("\\b");
                        atom_count += 1;
                        self.advance_char();
                    }
                    _ => return Err(ParseError::new(self.input, start, "root")),
                }
                continue;
            }

            regex.push_str(&escape_literal_char(ch));
            atom_count += 1;
            self.advance_char();
        }
        Err(ParseError::new(self.input, start, "root"))
    }

    fn parse_raw(&mut self) -> Result<CompiledAtom, ParseError> {
        let start = self.offset;
        self.advance_char();
        let mut regex = String::new();
        while let Some(ch) = self.peek_char() {
            if ch == '`' {
                self.advance_char();
                return Ok(CompiledAtom {
                    atom_count: count_regex_atoms(&regex),
                    regex,
                });
            }
            if ch == '\\' {
                self.advance_char();
                let escaped = self.peek_char().ok_or_else(|| ParseError::new(self.input, start, "root"))?;
                match escaped {
                    '\\' => {
                        regex.push_str("\\\\");
                        self.advance_char();
                    }
                    '`' => {
                        regex.push('`');
                        self.advance_char();
                    }
                    _ => return Err(ParseError::new(self.input, start, "root")),
                }
                continue;
            }
            regex.push(ch);
            self.advance_char();
        }
        Err(ParseError::new(self.input, start, "root"))
    }

    fn parse_symbol(&mut self) -> Result<Symbol, ParseError> {
        let start = self.offset;
        self.expect_char('<', "symbol_identifier")?;
        let mut parts = Vec::new();
        loop {
            self.skip_ws();
            let ident_start = self.offset;
            let ident = self
                .parse_identifier()
                .ok_or_else(|| ParseError::new(self.input, ident_start.max(start + 1), "symbol_identifier"))?;
            parts.push(ident);
            self.skip_ws();
            if self.peek_char() == Some('>') {
                break;
            }
        }
        self.expect_char('>', "symbol_identifier")?;
        let name = parts.join(" ");
        Ok(match name.as_str() {
            "char" => Symbol::Char,
            "space" => Symbol::Space,
            "whitespace" => Symbol::Whitespace,
            "digit" => Symbol::Digit,
            "word" => Symbol::Word,
            "newline" => Symbol::Newline,
            "tab" => Symbol::Tab,
            "return" => Symbol::Return,
            "null" => Symbol::Null,
            "backspace" => Symbol::Backspace,
            "boundary" => Symbol::Boundary,
            "start" => Symbol::Start,
            "end" => Symbol::End,
            _ => Symbol::Unknown(name),
        })
    }

    fn parse_identifier(&mut self) -> Option<String> {
        let start = self.offset;
        let mut out = String::new();
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_alphabetic() || ch == '_' {
                out.push(ch);
                self.advance_char();
            } else {
                break;
            }
        }
        if out.is_empty() {
            self.offset = start;
            None
        } else {
            Some(out)
        }
    }

    fn try_parse_digits(&mut self) -> Option<String> {
        let start = self.offset;
        let mut out = String::new();
        while let Some(ch) = self.peek_char() {
            if ch.is_ascii_digit() {
                out.push(ch);
                self.advance_char();
            } else {
                break;
            }
        }
        if out.is_empty() {
            self.offset = start;
            None
        } else {
            Some(out)
        }
    }

    fn consume_keyword(&mut self, keyword: &str) -> bool {
        let checkpoint = self.offset;
        self.skip_ws();
        if !self.input[self.offset..].starts_with(keyword) {
            self.offset = checkpoint;
            return false;
        }
        let end = self.offset + keyword.len();
        let next = self.input[end..].chars().next();
        if next.is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_' || ch.is_ascii_digit()) {
            self.offset = checkpoint;
            return false;
        }
        self.offset = end;
        true
    }

    fn expect_char(&mut self, ch: char, expected: &'static str) -> Result<(), ParseError> {
        self.skip_ws();
        if self.peek_char() == Some(ch) {
            self.advance_char();
            Ok(())
        } else {
            Err(self.error_here(expected))
        }
    }

    fn skip_ws(&mut self) {
        while let Some(ch) = self.peek_char() {
            if ch.is_whitespace() {
                self.advance_char();
            } else {
                break;
            }
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.input[self.offset..].chars().next()
    }

    fn advance_char(&mut self) {
        if let Some(ch) = self.peek_char() {
            self.offset += ch.len_utf8();
        }
    }

    fn is_eof(&self) -> bool {
        self.offset >= self.input.len()
    }

    fn error_here(&self, expected: &'static str) -> ParseError {
        ParseError::new(self.input, self.offset, expected)
    }
}

fn escape_literal_char(ch: char) -> String {
    match ch {
        '.' | '+' | '*' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '^' | '$' | '|' | '\\' => {
            format!("\\{ch}")
        }
        _ => ch.to_string(),
    }
}

fn count_regex_atoms(pattern: &str) -> usize {
    if pattern.is_empty() {
        return 0;
    }
    let chars: Vec<char> = pattern.chars().collect();
    let mut idx = 0;
    let mut atoms = 0;
    while idx < chars.len() {
        match chars[idx] {
            '\\' => {
                atoms += 1;
                idx += 1;
                if idx < chars.len() && chars[idx] == 'k' && idx + 1 < chars.len() && chars[idx + 1] == '<' {
                    idx += 2;
                    while idx < chars.len() && chars[idx] != '>' {
                        idx += 1;
                    }
                } else if idx < chars.len() && chars[idx] == 'p' {
                    while idx < chars.len() && chars[idx] != '}' {
                        idx += 1;
                    }
                }
                idx += 1;
            }
            '[' => {
                atoms += 1;
                idx += 1;
                while idx < chars.len() {
                    if chars[idx] == '\\' {
                        idx += 2;
                        continue;
                    }
                    if chars[idx] == ']' {
                        idx += 1;
                        break;
                    }
                    idx += 1;
                }
            }
            '(' => {
                atoms += 1;
                idx += 1;
                let mut depth = 1;
                while idx < chars.len() && depth > 0 {
                    if chars[idx] == '\\' {
                        idx += 2;
                        continue;
                    }
                    match chars[idx] {
                        '(' => depth += 1,
                        ')' => depth -= 1,
                        _ => {}
                    }
                    idx += 1;
                }
            }
            '^' | '$' => {
                atoms += 1;
                idx += 1;
            }
            _ => {
                atoms += 1;
                idx += 1;
            }
        }
    }
    atoms
}

